[BurstCompile]
struct CullJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float3> positions;
    public float3 camera;
    public float maxDistSq;
    public NativeList<int>.ParallelWriter visible;   // append-only from many threads

    public void Execute(int i)
    {
        if (math.distancesq(positions[i], camera) < maxDistSq)
        {
            visible.AddNoResize(i);                  // takes a slot atomically
        }
    }
}

JobHandle ScheduleCull(NativeArray<float3> positions, float3 camera, out NativeList<int> visible)
{
    visible = new NativeList<int>(positions.Length, Allocator.TempJob);   // capacity up front
    var job = new CullJob { positions = positions, camera = camera, maxDistSq = 50f * 50f };
    job.visible = visible.AsParallelWriter();
    return job.Schedule(positions.Length, 64);
}

