var stream = new NativeStream(count, Allocator.TempJob);   // one buffer per index
job.contacts = stream.AsWriter();                          // NativeStream.Writer field

public void Execute(int i)
{
    contacts.BeginForEachIndex(i);
    for (int j = 0; j < neighbours; j++)
        if (Touch(i, j)) contacts.Write(new Contact(i, j));
    contacts.EndForEachIndex();
}

// later, on one thread: buffers in index order
var reader = stream.AsReader();
for (int i = 0; i < reader.ForEachCount; i++)
{
    int n = reader.BeginForEachIndex(i);
    for (int k = 0; k < n; k++) Resolve(reader.Read<Contact>());
    reader.EndForEachIndex();
}

[BurstCompile]
struct ScanJob : IJob
{
    [ReadOnly] public NativeArray<int> counts;
    public NativeArray<int> offsets;
    public NativeReference<int> total;

    public void Execute()
    {
        int sum = 0;
        for (int i = 0; i < counts.Length; i++)
        {
            offsets[i] = sum;          // exclusive: everything before i
            sum += counts[i];
        }
        total.Value = sum;
    }
}

